// Startup crash-recovery sweep, mirroring ListNonTerminalRebootOperations.
func (q *Queries) ListNonTerminalDatabaseOperations(ctx context.Context) ([]DatabaseOperation, error) {
	rows, err := q.db.Query(ctx, listNonTerminalDatabaseOperations)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DatabaseOperation{}
	for rows.Next() {
		var i DatabaseOperation
		if err := rows.Scan(
			&i.ID,
			&i.DatabaseID,
			&i.OperationType,
			&i.Status,
			&i.RequestedBy,
			&i.Reason,
			&i.Parameters,
			&i.CommandPreview,
			&i.RecommendationID,
			&i.ConfirmedAt,
			&i.StartedAt,
			&i.CompletedAt,
			&i.TimeoutAt,
			&i.ResultSummary,
			&i.ResultDetail,
			&i.ErrorSummary,
			&i.HealthBefore,
			&i.HealthAfter,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

